// Collect PDF files from either trigger and emit ONE item per PDF with the
// file in binary property "data".
//  - Webhook upload (multipart/form-data, any field name): first PDF only.
//  - Gmail trigger (attachments downloaded as attachment_0, attachment_1 ...):
//    every PDF attachment of every email.
// Mode: Run once for all items.

const MAX_BYTES = 10 * 1024 * 1024;
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const isWebhook = j.headers !== undefined && j.body !== undefined;
  const source = isWebhook ? 'webhook' : 'gmail';
  const binary = item.binary || {};

  const pdfKeys = Object.keys(binary).filter((k) => {
    const b = binary[k] || {};
    return /pdf/i.test(b.mimeType || '') || /\.pdf$/i.test(b.fileName || '');
  });

  const sender = source === 'gmail'
    ? String((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '').toLowerCase()
    : '';

  if (pdfKeys.length === 0) {
    if (isWebhook) {
      out.push({ json: { ok: false, source, error: 'No PDF file found. Send multipart/form-data with a PDF in field "file".' } });
    }
    continue; // Gmail: emails without PDFs are ignored
  }

  for (const key of isWebhook ? pdfKeys.slice(0, 1) : pdfKeys) {
    const b = binary[key];
    const size = Number(b.bytes || b.fileSizeBytes || 0);
    if (size > MAX_BYTES) {
      if (isWebhook) out.push({ json: { ok: false, source, error: `PDF is larger than ${MAX_BYTES / 1024 / 1024} MB.` } });
      continue;
    }
    out.push({
      json: {
        ok: true,
        source,
        file_name: b.fileName || `${key}.pdf`,
        sender_email: sender,
        email_subject: source === 'gmail' ? String(j.subject || '') : '',
        gmail_message_id: source === 'gmail' ? String(j.id || '') : '',
        received_at: new Date().toISOString(),
      },
      binary: { data: b },
    });
  }
}

return out;

// Exact-duplicate detection by file hash BEFORE any LLM call (saves cost).
// The registry lives in workflow static data (persisted for production
// executions). Capped to the most recent 20,000 files.
// Mode: Run once for each item.

const store = $getWorkflowStaticData('global');
store.invoiceFiles = store.invoiceFiles || {};

const j = $input.item.json;
const hash = j.file_sha256;
const seen = store.invoiceFiles[hash];

if (!seen) {
  store.invoiceFiles[hash] = { at: new Date().toISOString(), file: j.file_name };
  const keys = Object.keys(store.invoiceFiles);
  if (keys.length > 20000) {
    keys.sort((a, b) => store.invoiceFiles[a].at.localeCompare(store.invoiceFiles[b].at))
      .slice(0, keys.length - 20000).forEach((k) => delete store.invoiceFiles[k]);
  }
}

return {
  json: {
    ...j,
    duplicate_file: Boolean(seen),
    duplicate_of: seen || null,
  },
  // The Crypto node does not pass binary data through - re-attach the PDF.
  binary: $('Collect PDF files').item.binary,
};

// Exact same PDF was processed before: skip the LLM, send to review.
// Mode: Run once for each item.
const j = $input.item.json;
return {
  json: {
    status: 'needs_review',
    issues: [{ code: 'duplicate_file', message: `This exact file was already processed on ${String(j.duplicate_of && j.duplicate_of.at).slice(0, 10)} (${j.duplicate_of && j.duplicate_of.file})` }],
    warnings: [],
    invoice: null,
  },
};

// No usable text: either the PDF could not be parsed at all, or it has no
// text layer (scanned image). Needs OCR or a human. Mode: Run once for each item.
const j = $input.item.json;
const unreadable = Boolean(j.error);
return {
  json: {
    status: 'needs_review',
    issues: [unreadable
      ? { code: 'unreadable_pdf', message: 'The file could not be parsed as a PDF: ' + String(j.error.message || j.error).slice(0, 200) }
      : { code: 'no_text_layer', message: `No extractable text found (${j.numpages || '?'} page(s)). The PDF is probably a scan; OCR is not part of this workflow.` }],
    warnings: [],
    invoice: null,
  },
};

// Parse the LLM extraction and run deterministic business validation.
// The LLM only reads the document; every check below is plain code, so a
// wrong total can never be "explained away" by the model.
// Mode: Run once for each item.
//
// Errors (-> review queue): missing required fields, line amount != qty x unit,
// line items != subtotal, subtotal + tax != total, tax rate mismatch,
// impossible dates, invalid currency, duplicate invoice number (same vendor).
// Warnings (still accepted): old invoice, unusually long payment terms,
// non-invoice document type.

const cfg = $('Config').first().json;
const file = $('Check duplicate file').item.json;
const input = $input.item.json;
const TOL = Math.max(0, Number(cfg.amountTolerance) || 0.02);

const issues = [];
const warnings = [];
const issue = (code, message) => issues.push({ code, message });
const warn = (code, message) => warnings.push({ code, message });

// ---- parse -----------------------------------------------------------------
// --- included from src/code/shared/read-llm-json.js ---------------------------
// The Basic LLM Chain returns one of three shapes, depending on model setup:
//   { text: "<raw model output>" }      (string output, e.g. with a fallback model)
//   { ...parsedJsonObject }             (JSON mode: n8n already parsed it)
//   { ...inputFields, error: "..." }    (error output of the chain node - it keeps
//                                        the input item's fields and adds "error")
// Returns { data, raw, error } where data is a plain object or null.
function readLlmJson(input) {
  if (input && input.error) {
    const e = input.error;
    return { data: null, raw: '', error: 'LLM request failed: ' + String((e && e.message) || e).slice(0, 300) };
  }
  let raw;
  let data = null;
  if (input && typeof input.text === 'string' && Object.keys(input).length === 1) {
    raw = input.text;
    const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try { data = JSON.parse(cleaned); } catch {
      const m = cleaned.match(/\{[\s\S]*\}/);
      if (m) { try { data = JSON.parse(m[0]); } catch { /* not JSON */ } }
    }
  } else {
    data = input;
    raw = JSON.stringify(input);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { data: null, raw: String(raw || ''), error: 'Output is not a single JSON object' };
  }
  return { data, raw: String(raw), error: null };
}
// --- end include ----------------------------------------------------------------

const parsed = readLlmJson(input);
const data = parsed.data;
if (parsed.error) issue('extraction_failed', parsed.error);

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).replace(/[^\d.,-]/g, '');
  // "1.234,56" (EU) vs "1,234.56" (US)
  const normalized = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  const n = Number(normalized);
  return Number.isFinite(n) ? n : null;
};
const r2 = (n) => Math.round(n * 100) / 100;
const fmt = (n) => (n === null || n === undefined ? 'n/a' : Number(n).toFixed(2));
const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const isoDate = (v) => {
  const s = str(v);
  if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(s + 'T00:00:00Z');
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s ? null : s;
};

let invoice = null;
if (data) {
  const items = Array.isArray(data.line_items) ? data.line_items : [];
  invoice = {
    document_type: str(data.document_type) || 'invoice',
    vendor_name: str(data.vendor_name),
    vendor_tax_id: str(data.vendor_tax_id),
    invoice_number: str(data.invoice_number),
    issue_date: isoDate(data.issue_date),
    due_date: isoDate(data.due_date),
    currency: (str(data.currency) || '').toUpperCase() || null,
    bill_to: str(data.bill_to),
    line_items: items.map((li) => ({
      description: str(li && li.description) || '',
      quantity: num(li && li.quantity),
      unit_price: num(li && li.unit_price),
      amount: num(li && li.amount),
    })),
    subtotal: num(data.subtotal),
    tax_amount: num(data.tax_amount),
    tax_rate_percent: num(data.tax_rate_percent),
    total: num(data.total),
  };

  // ---- required fields -----------------------------------------------------
  if (!invoice.vendor_name) issue('missing_vendor', 'Vendor name is missing');
  if (!invoice.invoice_number) issue('missing_invoice_number', 'Invoice number is missing');
  if (!invoice.issue_date) issue('invalid_issue_date', `Issue date is missing or not a valid date (${JSON.stringify(data.issue_date)})`);
  if (!invoice.currency || !/^[A-Z]{3}$/.test(invoice.currency)) issue('invalid_currency', `Currency must be a 3-letter ISO code (got ${JSON.stringify(data.currency)})`);
  if (invoice.total === null) issue('missing_total', 'Total amount is missing');
  if (invoice.line_items.length === 0) issue('missing_line_items', 'No line items found');
  if (invoice.document_type !== 'invoice') warn('not_an_invoice', `Document looks like a ${invoice.document_type}`);

  // ---- line items ----------------------------------------------------------
  invoice.line_items.forEach((li, i) => {
    if (li.amount === null) { issue('line_amount_missing', `Line ${i + 1} has no amount`); return; }
    if (li.quantity !== null && li.unit_price !== null) {
      const expected = r2(li.quantity * li.unit_price);
      if (Math.abs(expected - li.amount) > TOL) {
        issue('line_amount_mismatch', `Line ${i + 1} ("${li.description.slice(0, 40)}"): ${li.quantity} x ${fmt(li.unit_price)} = ${fmt(expected)}, but the line amount is ${fmt(li.amount)}`);
      }
    }
  });
  const lineSum = r2(invoice.line_items.reduce((s, li) => s + (li.amount || 0), 0));
  invoice.line_items_sum = lineSum;

  // ---- subtotal / tax / total ---------------------------------------------
  const tolN = Math.max(TOL, invoice.line_items.length * 0.01); // per-line rounding
  if (invoice.subtotal !== null && invoice.line_items.length) {
    if (Math.abs(lineSum - invoice.subtotal) > tolN) {
      issue('line_items_sum_mismatch', `Line items add up to ${fmt(lineSum)} but the stated subtotal is ${fmt(invoice.subtotal)} (difference ${fmt(r2(invoice.subtotal - lineSum))})`);
    }
  }
  const base = invoice.subtotal !== null ? invoice.subtotal : lineSum;
  const tax = invoice.tax_amount || 0;
  if (invoice.total !== null && Math.abs(r2(base + tax) - invoice.total) > TOL) {
    issue('total_mismatch', `Subtotal ${fmt(base)} + tax ${fmt(tax)} = ${fmt(r2(base + tax))}, but the stated total is ${fmt(invoice.total)}`);
  }
  if (invoice.tax_rate_percent !== null && invoice.tax_amount !== null) {
    const expectedTax = r2(base * invoice.tax_rate_percent / 100);
    if (Math.abs(expectedTax - invoice.tax_amount) > tolN) {
      issue('tax_rate_mismatch', `${invoice.tax_rate_percent}% of ${fmt(base)} is ${fmt(expectedTax)}, but the stated tax is ${fmt(invoice.tax_amount)}`);
    }
  }
  if (invoice.total !== null && invoice.total <= 0 && invoice.document_type === 'invoice') {
    issue('non_positive_total', 'Total must be greater than zero for an invoice');
  }

  // ---- dates -----------------------------------------------------------------
  const today = new Date();
  const dayMs = 86400000;
  if (invoice.issue_date) {
    const issued = new Date(invoice.issue_date + 'T00:00:00Z');
    if (issued.getTime() - today.getTime() > dayMs) issue('issue_date_in_future', `Issue date ${invoice.issue_date} is in the future`);
    if (today.getTime() - issued.getTime() > 365 * dayMs) warn('old_invoice', `Issue date ${invoice.issue_date} is more than a year ago`);
    if (invoice.due_date) {
      const due = new Date(invoice.due_date + 'T00:00:00Z');
      if (due < issued) issue('due_before_issue', `Due date ${invoice.due_date} is before issue date ${invoice.issue_date}`);
      else if ((due - issued) / dayMs > 120) warn('long_payment_terms', `Payment terms of ${Math.round((due - issued) / dayMs)} days`);
    }
  }

  // ---- duplicate invoice number (same vendor) --------------------------------
  if (invoice.vendor_name && invoice.invoice_number) {
    const key = (invoice.vendor_name.toLowerCase().replace(/[^a-z0-9]/g, '') + '|' +
      invoice.invoice_number.toLowerCase().replace(/[^a-z0-9]/g, ''));
    const store = $getWorkflowStaticData('global');
    store.invoiceNumbers = store.invoiceNumbers || {};
    const prev = store.invoiceNumbers[key];
    if (prev) {
      issue('duplicate_invoice_number', `Invoice ${invoice.invoice_number} from ${invoice.vendor_name} was already processed on ${prev.at.slice(0, 10)} (file ${prev.file})`);
    } else if (issues.length === 0) {
      // Only accepted invoices are registered, so a corrected re-send is not blocked.
      store.invoiceNumbers[key] = { at: new Date().toISOString(), file: file.file_name };
    }
  }
}

return {
  json: {
    status: issues.length === 0 ? 'valid' : 'needs_review',
    issues,
    warnings,
    invoice,
  },
};

// Final record + route for every path (valid, validation failed, duplicate
// file, no text layer). Mode: Run once for each item.
//   route = "accept"  -> Invoices sheet
//   route = "review"  -> Review queue sheet + Slack
//   route = "dry_run" -> no side effects (AUTOMATION_DRY_RUN=true)

const cfg = $('Config').first().json;
const file = $('Check duplicate file').item.json;
const r = $input.item.json; // { status, issues, warnings, invoice }
const inv = r.invoice || {};
const issues = r.issues || [];
const warnings = r.warnings || [];

const route = cfg.dryRun ? 'dry_run' : r.status === 'valid' ? 'accept' : 'review';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const slackText = [
  `:receipt: *Invoice needs review* - ${esc(inv.vendor_name || 'unknown vendor')} ${esc(inv.invoice_number || '')}`,
  `*File:* ${esc(file.file_name)} (${file.source}${file.sender_email ? ' from ' + esc(file.sender_email) : ''})`,
  inv.total !== undefined && inv.total !== null ? `*Total:* ${inv.total} ${esc(inv.currency || '')}` : '',
  '*Problems:*',
  ...issues.map((i) => `• \`${i.code}\` ${esc(i.message)}`),
].filter(Boolean).join('\n');

return {
  json: {
    route,
    status: r.status,
    processed_at: new Date().toISOString(),
    source: file.source,
    file_name: file.file_name,
    file_sha256: file.file_sha256,
    sender_email: file.sender_email || '',
    vendor_name: inv.vendor_name || '',
    vendor_tax_id: inv.vendor_tax_id || '',
    invoice_number: inv.invoice_number || '',
    issue_date: inv.issue_date || '',
    due_date: inv.due_date || '',
    currency: inv.currency || '',
    subtotal: inv.subtotal ?? '',
    tax_amount: inv.tax_amount ?? '',
    tax_rate_percent: inv.tax_rate_percent ?? '',
    total: inv.total ?? '',
    line_items_count: (inv.line_items || []).length,
    line_items_json: JSON.stringify(inv.line_items || []),
    issues: issues.map((i) => `${i.code}: ${i.message}`).join(' | '),
    warnings: warnings.map((w) => `${w.code}: ${w.message}`).join(' | '),
    // not Sheets columns:
    issue_codes: issues.map((i) => i.code),
    invoice: r.invoice || null,
    slack_text: slackText,
  },
};

// HTTP response for the upload webhook. Mode: Run once for all items.
const rec = $('Decide route').first().json;
return [{
  json: {
    statusCode: 200,
    body: {
      status: rec.status,                     // "valid" | "needs_review"
      route: rec.route,                       // "accept" | "review" | "dry_run"
      file_name: rec.file_name,
      file_sha256: rec.file_sha256,
      issues: rec.issue_codes,
      issue_details: rec.issues ? rec.issues.split(' | ') : [],
      warnings: rec.warnings ? rec.warnings.split(' | ') : [],
      invoice: rec.invoice,
    },
  },
}];
